int64_t iso10126_d2_padding(const int64_t*v,size_t n,uint8_t*out,size_t cap){if(!v||n<2||n>66)return -1;int64_t mode=v[0];if(mode==0){if(n<3)return -1;int64_t off=v[1],len=v[2];if(len<1||len>64||off<0||off>=len||n!=3+(size_t)off+(size_t)(len-off-1))return -1;for(size_t i=3;i<n;i++)if(v[i]<0||v[i]>255)return -1;for(size_t i=3+(size_t)off;i<n;i++)if(v[i]>=255)return -1;size_t bytes=(size_t)len+1;if(!out||cap<bytes)return -2;uint8_t count=(uint8_t)(len-off);out[0]=count;size_t at=1;for(int64_t i=0;i<off;i++)out[at++]=(uint8_t)v[3+i];for(size_t i=3+(size_t)off;i<n;i++)out[at++]=(uint8_t)v[i];out[at]=count;return (int64_t)bytes;}if((mode!=1&&mode!=2)||n<3)return -1;int64_t len=v[1];if(len<1||len>64||n!=2+(size_t)len)return -1;for(size_t i=2;i<n;i++)if(v[i]<0||v[i]>255)return -1;int64_t count=v[n-1];if(count<1||count>len)return -1;size_t bytes=mode==1?(size_t)(len-count):1;if(!out||cap<bytes)return -2;if(mode==1){for(size_t i=0;i<bytes;i++)out[i]=(uint8_t)v[i+2];}else out[0]=(uint8_t)count;return (int64_t)bytes;}
